<?php

/* @autogenerated */
declare(strict_types=1);

require_once __DIR__ . '/FormsTestCase.php';

use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms\TermsAndGdprConsentForm;
use Civi\Lughauth\Features\Oidc\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\Oidc\Theme\Application\DecorateHtml;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\Oidc\User\Domain\PublicLoginAuthResponse;
use Civi\Lughauth\Features\Oidc\Consent\Domain\TermsOfUseAcceptance;
use Civi\Lughauth\Features\Oidc\Consent\Application\Usecase\TermsOfUseConsentUsecase;
use Civi\Lughauth\Features\Oidc\Consent\Application\Usecase\GdprConsentUsecase;
use Civi\Lughauth\Features\Oidc\Consent\Domain\Gateway\GdprConsentGateway;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;

/**
 * Unit tests for {@see TermsAndGdprConsentForm} step integration.
 */
#[AllowMockObjectsWithoutExpectations]
final class TermsAndGdprConsentFormStepUnitTest extends FormsTestCase
{
    public function testAuthenticateStoresConsentAndProceeds(): void
    {
        $input = $this->buildInput(
            ['accept' => 'accept', 'consent' => 'consent-1', 'conditions' => 'terms'],
            new ChallengesState(username: 'user-1')
        );
        $authResponse = $this->createMock(PublicLoginAuthResponse::class);

        $authenticator = $this->createMock(AuthenticateUser::class);
        $authenticator->expects($this->once())
            ->method('preAuthenticate')
            ->willReturn($authResponse);

        $consent = $this->createMock(TermsOfUseConsentUsecase::class);
        $consent->expects($this->once())
            ->method('storeAcceptedConsent')
            ->with('tenant1', 'user-1', ['client-123'], $this->isInstanceOf(TermsOfUseAcceptance::class));

        $gdprGateway = $this->createMock(GdprConsentGateway::class);
        $gdprGateway->expects($this->once())
            ->method('pendingPurposes')
            ->with('tenant1', 'user-1')
            ->willReturn([]);
        $gdprConsent = new GdprConsentUsecase($gdprGateway);

        $form = new TermsAndGdprConsentForm(
            $this->createMock(MessageProvider::class),
            $authenticator,
            $consent,
            $gdprConsent,
            $this->createMock(DecorateHtml::class),
            $this->createMock(HtmlSecurer::class)
        );

        $result = $form->authenticate($input);

        $this->assertInstanceOf(StepResult::class, $result);
        $this->assertSame(StepResult::TYPE_PROCEED, $result->type);
        $this->assertSame($authResponse, $result->authResponse);
        $this->assertSame($input->challenges, $result->challenges);
    }
}
